using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
enum ScrollAppendOutcome {None,Added,Unchanged,Rejected,Limit}
class ScrollStitcher:IDisposable {
 public ScrollAppendOutcome LastOutcome{get;private set;}public Bitmap Image{get;private set;}public int Frames{get;private set;}public string Status="向下小幅滚动页面，停稳后自动拼接";PixelRows previous;
 public const int MaxHeight=30000;public const long MaxPixels=40000000;
 bool upward;
 public ScrollStitcher(Bitmap first):this(first,false){}
 public ScrollStitcher(Bitmap first,bool upward){this.upward=upward;if(first.Width<80||first.Height<80)throw new Exception("滚动区域至少需要 80 × 80 像素");if(first.Height>MaxHeight||(long)first.Width*first.Height>MaxPixels)throw new Exception("截图区域过大，请缩小选区");Image=new Bitmap(first);if(upward){using(var flipped=new Bitmap(first)){flipped.RotateFlip(RotateFlipType.RotateNoneFlipY);previous=new PixelRows(flipped);}}else previous=new PixelRows(first);Frames=1;}
 public bool Append(Bitmap next){LastOutcome=ScrollAppendOutcome.Rejected;if(next.Width!=previous.Width||next.Height!=previous.Height){Status="选区尺寸发生变化，请重新开始";return false;}Bitmap flipped=null;try{Bitmap normalized=next;if(upward){flipped=new Bitmap(next);flipped.RotateFlip(RotateFlipType.RotateNoneFlipY);normalized=flipped;}var rows=new PixelRows(normalized);if(previous.Difference(rows)<.8){LastOutcome=ScrollAppendOutcome.Unchanged;Status="页面未变化或已到"+(upward?"顶部":"底部");return false;}int footer=previous.FixedFooter(rows);int shift;double quality;if(!previous.FindShift(rows,footer,out shift,out quality)){Status="未找到可靠重叠，自动滚动将暂停";return false;}if(Image.Height+shift>MaxHeight||(long)Image.Width*(Image.Height+shift)>MaxPixels){LastOutcome=ScrollAppendOutcome.Limit;Status="已达到长图上限 · 请按 Enter 完成";return false;}var combined=new Bitmap(Image.Width,Image.Height+shift,PixelFormat.Format24bppRgb);using(var g=Graphics.FromImage(combined)){if(upward){g.DrawImage(next,new Rectangle(0,0,next.Width,shift+footer),new Rectangle(0,0,next.Width,shift+footer),GraphicsUnit.Pixel);g.DrawImage(Image,new Rectangle(0,shift+footer,Image.Width,Image.Height-footer),new Rectangle(0,footer,Image.Width,Image.Height-footer),GraphicsUnit.Pixel);}else{int keep=Image.Height-footer;g.DrawImage(Image,new Rectangle(0,0,Image.Width,keep),new Rectangle(0,0,Image.Width,keep),GraphicsUnit.Pixel);g.DrawImage(next,new Rectangle(0,keep,next.Width,shift+footer),new Rectangle(0,next.Height-footer-shift,next.Width,shift+footer),GraphicsUnit.Pixel);}}Image.Dispose();Image=combined;previous=rows;Frames++;LastOutcome=ScrollAppendOutcome.Added;Status="已拼接 "+Frames+" 帧 · "+Image.Width+" × "+Image.Height+" px";return true;}finally{if(flipped!=null)flipped.Dispose();}}
 public void Dispose(){if(Image!=null){Image.Dispose();Image=null;}}
 public sealed class PixelRows {
 public int Width,Height;const int Columns=32,Channels=96;byte[] data;float[] energy;
 public PixelRows(Bitmap source){Width=source.Width;Height=source.Height;data=new byte[Height*Channels];energy=new float[Height];using(var bitmap=new Bitmap(Width,Height,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(bitmap))g.DrawImageUnscaled(source,0,0);var locked=bitmap.LockBits(new Rectangle(0,0,Width,Height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{var scan=new byte[Math.Abs(locked.Stride)];for(int y=0;y<Height;y++){Marshal.Copy(IntPtr.Add(locked.Scan0,y*locked.Stride),scan,0,scan.Length);int low=255,high=0;for(int x=0;x<Columns;x++){int pixel=(int)((.06+.88*x/(Columns-1))*Math.Max(0,Width-1))*4;for(int c=0;c<3;c++){int value=scan[pixel+c];data[y*Channels+x*3+c]=(byte)value;low=Math.Min(low,value);high=Math.Max(high,value);}}energy[y]=high-low;}}finally{bitmap.UnlockBits(locked);}}}
 double RowDifference(PixelRows other,int a,int b){int sum=0;for(int c=0;c<Channels;c++)sum+=Math.Abs(data[a*Channels+c]-other.data[b*Channels+c]);return (double)sum/Channels;}
 public double Difference(PixelRows other){if(Width!=other.Width||Height!=other.Height)return 255;double score=0;int count=0;for(int y=0;y<Height;y+=Math.Max(1,Height/180)){score+=RowDifference(other,y,y);count++;}return score/Math.Max(1,count);}
 public int FixedFooter(PixelRows other){int rows=0,texture=0;for(int y=Height-1;y>=Height*3/4;y--){if(RowDifference(other,y,y)>1.2)break;rows++;if(energy[y]>18)texture++;}return texture>=4?rows:0;}
 double Score(PixelRows other,int shift,int footer){int start=Height/6,end=Height-footer-shift-Math.Max(5,Height/30);if(end-start<Math.Max(24,Height/10))return 999;double score=0;int count=0,informative=0;int step=Math.Max(1,(end-start)/100);for(int y=start;y<end;y+=step){if(energy[y+shift]<12&&other.energy[y]<12)continue;score+=RowDifference(other,y+shift,y);count++;if(energy[y+shift]>18||other.energy[y]>18)informative++;}if(count<8||informative<6)return 999;return score/count;}
 public bool FindShift(PixelRows other,int footer,out int shift,out double quality){shift=0;quality=999;int max=Height-footer-Math.Max(40,Height/3),stride=1;var candidates=new List<KeyValuePair<int,double>>();for(int n=1;n<=max;n+=stride){double score=Score(other,n,footer);candidates.Add(new KeyValuePair<int,double>(n,score));if(score<quality){quality=score;shift=n;}}int coarse=shift;for(int n=Math.Max(1,coarse-stride);n<=Math.Min(max,coarse+stride);n++){double score=Score(other,n,footer);if(score<quality){quality=score;shift=n;}}double second=999;foreach(var entry in candidates)if(Math.Abs(entry.Key-shift)>Math.Max(6,stride*2))second=Math.Min(second,entry.Value);return quality<5&&second>quality+1.5&&shift>=1;}
 }
}
